#!/usr/bin/env node
/**
 * Dashboard v4 static build — concat only, no dependencies.
 *
 *   node scripts/build-css.mjs          # write generated files
 *   node scripts/build-css.mjs --check  # exit 1 if the checked-in output is stale
 *
 * Outputs (committed — CI has no build step):
 *   static/styles/shell-critical.css  first-paint CSS: one file, one @layer line
 *   static/styles/tabs-lazy.css       everything the tab chunks need
 *   static/shell.js                   shell core: the only script in <head>
 *
 * Shell-critical rules are marked in the hand-written sources so those files
 * stay the source of truth (the CSS contract tests read them verbatim):
 *   @shell:begin ... @shell:end   (comment markers)
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const STATIC = join(ROOT, "nous/api/http/static");

/* Fixed order, asserted at the bottom. The cascade order of the old <link>
   sequence is preserved: variables, reset, layout, theme, components, chat,
   chat-mobile, utilities, sections-last (unlayered, so it must stay last). */
const SHELL_ORDER = ["variables", "reset", "layout", "theme"];
const LAZY_ORDER = ["components", "chat", "chat-mobile", "utilities", "sections"];
const FULLY_SHELL = new Set(SHELL_ORDER);

/* The one @layer statement (variables.css:1), hoisted to line 1 of each
   bundle: a statement after a block is silently ignored. */
const LAYER_DECL = "@layer reset, base, tokens, components, utilities, overrides;";

/* Shell core in dependency order. namespace defines N; store/dom/api/toast
   are used by everything below; base.js drives the tabs; ready.js adds the
   lazy bootstrap (N.Core.whenReady); delegation handles [data-action]. */
const SHELL_JS = [
  "core/namespace.js",
  "core/store.js",
  "core/dom.js",
  "core/api.js",
  "core/toast.js",
  "core/sse.js",
  "core/theme.js",
  "components/skeleton.js",
  "base.js",
  "core/delegation.js",
  "core/ready.js",
];

const read = (rel) => readFileSync(join(STATIC, rel), "utf8");

/* Split each source into its shell part and the rest. Files in FULLY_SHELL
   start in shell; files with no markers stay wholly in one side. */
function split() {
  const shell = [];
  const lazy = [];
  for (const name of [...SHELL_ORDER, ...LAZY_ORDER]) {
    const head = "/* ---- styles/" + name + ".css ---- */";
    let inShell = FULLY_SHELL.has(name);
    let shellText = "";
    let lazyText = "";
    for (const line of read("styles/" + name + ".css").split("\n")) {
      if (line.includes("@shell:begin")) { inShell = true; continue; }
      if (line.includes("@shell:end")) { inShell = false; continue; }
      if (line.trim() === LAYER_DECL) continue;
      if (inShell) shellText += line + "\n";
      else lazyText += line + "\n";
    }
    if (shellText.trim()) shell.push(head + "\n" + shellText);
    if (lazyText.trim()) lazy.push(head + "\n" + lazyText);
  }
  return { shell, lazy };
}

const banner = (what) =>
  "/* GENERATED by scripts/build-css.mjs — edit the sources, not this file.\n   " + what + " */";

const { shell, lazy } = split();
const outputs = new Map([
  [
    "styles/shell-critical.css",
    [LAYER_DECL, banner("first paint: variables, reset, layout, theme + shell blocks"), ...shell].join("\n"),
  ],
  [
    "styles/tabs-lazy.css",
    [LAYER_DECL, banner("tab chunks: everything not needed for first paint, sections last"), ...lazy].join("\n"),
  ],
  [
    "shell.js",
    banner("concat of: " + SHELL_JS.join(" ")) +
      "\n" +
      SHELL_JS.map((p) => "/* ---- " + p + " ---- */\n" + read(p)).join("\n"),
  ],
]);

/* Self-checks: the bundle shapes the CSS contract depends on. */
function assertCss(rel, css) {
  const lines = css.split("\n");
  if (lines[0] !== LAYER_DECL) throw new Error(rel + ": @layer statement must be line 1");
  const decls = lines.filter((l) => l.trim().startsWith("@layer ") && l.trim().endsWith(";"));
  if (decls.length !== 1) throw new Error(rel + ": expected 1 @layer statement, got " + decls.length);
  const marks = lines.filter((l) => l.startsWith("/* ---- styles/"));
  if (rel.endsWith("tabs-lazy.css") && !marks[marks.length - 1].includes("sections.css")) {
    throw new Error(rel + ": sections.css (unlayered) must be the last source");
  }
  if (rel.endsWith("shell-critical.css") && !marks.some((m) => m.includes("components.css"))) {
    throw new Error(rel + ": components.css shell block missing");
  }
}

let failed = false;
for (const [rel, content] of outputs) {
  if (rel.endsWith(".css")) assertCss(rel, content);
  const abs = join(STATIC, rel);
  if (process.argv.includes("--check")) {
    let current = null;
    try { current = readFileSync(abs, "utf8"); } catch {}
    if (current !== content) { console.error("stale: static/" + rel); failed = true; }
  } else {
    writeFileSync(abs, content);
    console.log("wrote static/" + rel + " (" + content.length + " B)");
  }
}
if (failed) process.exit(1);
